async function localServer(t, handler) {
  const server = createServer(handler);
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(async () => { server.closeAllConnections(); await new Promise(resolve => server.close(resolve)); });
  return 'http://127.0.0.1:' + server.address().port;
}

test('generated token method serializes both grants without seller credentials', async t => {
  const forms = [];
  const origin = await localServer(t, async (req, res) => {
    assert.equal(req.url, '/oauth/token');
    assert.equal(req.headers.authorization, undefined);
    assert.equal(req.headers['x-store'], undefined);
    assert.equal(req.headers['content-type'], 'application/x-www-form-urlencoded');
    let body = ''; for await (const chunk of req) body += chunk;
    forms.push(new URLSearchParams(body));
    res.setHeader('Content-Type', 'application/json');
    res.setHeader('X-Request-ID', 'grant-request');
    res.end(JSON.stringify({token_type:'Bearer', expires_in:3600, access_token:'access', refresh_token:'rotated'}));
  });
  const client = new SellApp({apiKey:'seller-key', store:'store', baseUrl:origin+'/api'});
  const code = await client.oauth.withResponse.exchangeOAuthToken({grantType:'authorization_code', code:'code + value', redirectUri:'https://example.com/callback', codeVerifier:'a'.repeat(43)});
  const refresh = await client.oauth.exchangeOAuthToken({grantType:'refresh_token', refreshToken:'refresh + value'});
  assert.equal(code.status,200); assert.equal(code.requestId,'grant-request'); assert.equal(refresh.accessToken,'access');
  assert.equal(forms.length,2);
  assert.equal(forms[0].get('grant_type'),'authorization_code');
  assert.equal(forms[0].get('code'),'code + value');
  assert.equal(forms[0].get('code_verifier'),'a'.repeat(43));
  assert.equal(forms[1].get('grant_type'),'refresh_token');
  assert.equal(forms[1].get('refresh_token'),'refresh + value');
});

test('successful HTML authorization and storage redirects preserve credential boundaries', async t => {
  let storageCalls = 0;
  let html = '<!doctype html><title>Consent</title>';
  const storage = await localServer(t, (_req,res) => { storageCalls++; res.end('storage'); });
  const origin = await localServer(t, (req,res) => {
    const path = new URL(req.url,'http://localhost').pathname;
    if (path === '/oauth/authorize') {
      assert.equal(req.headers.authorization,undefined); assert.equal(req.headers['x-store'],undefined);
      res.setHeader('Content-Type','text/html'); res.end(html);
    } else if (path === '/api/v2/me') {
      assert.equal(req.headers.authorization,'Bearer access'); assert.equal(req.headers['x-store'],undefined); res.end('{}');
    } else {
      assert.equal(req.headers.authorization,'Bearer access'); assert.equal(req.headers['x-store'],'store');
      res.writeHead(302,{Location:storage+'/file'}); res.end();
    }
  });
  const client = new SellApp({accessToken:'access',store:'store',baseUrl:origin+'/api'});
  await client.get('/v2/me');
  const page = await client.oauth.withResponse.getOAuthAuthorizationRequest({responseType:'code',clientId:'01992a65-e064-71ba-b38f-902b7966a6be',redirectUri:'https://example.com/callback',state:'state',codeChallenge:'a'.repeat(43),codeChallengeMethod:'S256'});
  assert.equal(page.status,200); assert.equal(page.headers.get('content-type'),'text/html');
  assert.equal(page.data,'<!doctype html><title>Consent</title>');
  for (html of ['123', '"consent"']) {
    const raw = await client.oauth.getOAuthAuthorizationRequest({responseType:'code',clientId:'01992a65-e064-71ba-b38f-902b7966a6be',redirectUri:'https://example.com/callback',state:'state',codeChallenge:'a'.repeat(43),codeChallengeMethod:'S256'});
    assert.equal(raw,html);
  }
  const redirect = await client.exports.withResponse.downloadExport({export:'export',expires:123,signature:'signature'});
  assert.equal(redirect.status,302); assert.equal(redirect.headers.get('location'),storage+'/file');
  assert.equal(storageCalls,0);
});

test('generated customer-session creation never retries an ambiguous response', async t => {
  let calls = 0;
  const origin = await localServer(t, (_req,res) => { calls++; res.writeHead(503,{'Retry-After':'0'}); res.end('ambiguous failure'); });
  const client = new SellApp({apiKey:'key',store:'store',baseUrl:origin,maxRetries:3});
  await assert.rejects(client.customerSessions.createCustomerSession({customerId:1,requestOptions:{maxRetries:3}}));
  assert.equal(calls,1);
  await assert.rejects(client.customerSessions.createCustomerSession({customerId:1,requestOptions:{idempotencyKey:'explicit-key'}}));
  assert.equal(calls,2);
});

test('API keys discover and provision accounts without a store header then target business reads', async t => {
  const calls = [];
  const store = {id:'12',name:'Launch Lab',slug:'launchlab'};
  const origin = await localServer(t, async (req,res) => {
    const path = new URL(req.url,'http://localhost').pathname;
    assert.equal(req.headers.authorization,'Bearer account-key');
    calls.push(path);
    res.setHeader('Content-Type','application/json');
    if (path === '/api/v2/products') {
      assert.equal(req.headers['x-store'],'launchlab');
      res.end(JSON.stringify({data:[]})); return;
    }
    assert.equal(req.headers['x-store'],undefined);
    if (req.method === 'POST') {
      assert.equal(req.headers['idempotency-key'],'create-launchlab-01');
      let body=''; for await (const chunk of req) body+=chunk;
      assert.deepEqual(JSON.parse(body),{name:'Launch Lab',slug:'launchlab'});
      res.writeHead(201);
      res.end(JSON.stringify({data:{...store,visibility:'PUBLIC',storefront_url:'https://launchlab.sell.app',dashboard_url:'https://sell.app/dashboard'}}));
    } else if(path.endsWith('/me')) res.end(JSON.stringify({data:{id:'42',username:'alex',email:'alex@example.com',credential_type:'sanctum'}}));
    else if(path.endsWith('/stores')) res.end(JSON.stringify({data:[store]}));
    else res.end(JSON.stringify({data:store}));
  });
  for (const configuredStore of ['', 'ignored-default']) {
    const account = new SellApp({apiKey:'account-key',store:configuredStore,baseUrl:origin+'/api'});
    assert.equal((await account.account.getAccount()).data.credentialType,'sanctum');
    assert.equal((await account.account.listStores()).data[0].id,'12');
    assert.equal((await account.account.getStore({store:12})).data.slug,'launchlab');
    const created = await account.account.createStore({name:'Launch Lab',slug:'launchlab',requestOptions:{headers:{'Idempotency-Key':'create-launchlab-01'}}});
    const selected = new SellApp({apiKey:'account-key',store:created.data.slug,baseUrl:origin+'/api'});
    assert.equal((await selected.products.list({limit:1})).data.length,0);
  }
  assert.equal(calls.length,10);
});


